import nl.slimov.app.NsJourney;import org.json.*;
public class NsJourneyTest {
 static int count;static void check(boolean value,String name){if(!value)throw new AssertionError(name);count++;System.out.println("PASS "+name);}
 static JSONObject event(String number,String when)throws Exception{return new JSONObject().put("product",new JSONObject().put("number",number).put("operatorName","NS").put("operatorCode","NS").put("longCategoryName","Intercity")).put("plannedTime",when).put("actualTime",when).put("plannedTrack","1").put("actualTrack","2");}
 static JSONObject node(String id,String prev,String next,String when)throws Exception{return new JSONObject().put("id",id).put("previousStopId",prev.isEmpty()?new JSONArray():new JSONArray().put(prev)).put("nextStopId",next.isEmpty()?new JSONArray():new JSONArray().put(next)).put("stop",new JSONObject().put("code",id).put("UICCode","8400"+id).put("lat",52).put("lng",5+Integer.parseInt(id)/100.0).put("namen",new JSONObject().put("lang","Station "+id))).put("arrivals",new JSONArray().put(event("123",when))).put("departures",new JSONArray().put(event("123",when))).put("status","STOP");}
 static JSONObject fixture()throws Exception{return new JSONObject().put("payload",new JSONObject().put("productNumbers",new JSONArray().put("123")).put("stops",new JSONArray().put(node("2","1","3","2026-11-13T10:15:00Z")).put(node("1","","2","2026-11-13T10:00:00Z")).put(node("3","2","","2026-11-13T10:30:00Z"))));}
 public static void main(String[] args)throws Exception{
  String when="2026-11-13T10:05:00Z";JSONObject t=NsJourney.make(fixture(),"123",when),l=t.getJSONArray("legs").getJSONObject(0);check(l.getJSONObject("from").getString("name").equals("Station 1"),"NS graph order is followed instead of JSON array order");check(l.getJSONArray("intermediateStops").length()==1,"intermediate station retained");check(l.getJSONObject("from").getString("departureTimestampReason").equals("PREDICTED"),"actualTime without observation proof is not historical OBSERVED");check(l.getJSONObject("from").getString("track").equals("2")&&l.getJSONObject("from").getString("scheduledTrack").equals("1"),"planned and current platforms remain separate");check(l.getString("tripId").equals(NsJourney.id("123",when)),"number and query instant form the exact NS reference");
  boolean mismatch=false;try{NsJourney.make(fixture(),"999",when);}catch(Exception e){mismatch=true;}check(mismatch,"another train number rejected");
  JSONObject branch=fixture();branch.getJSONObject("payload").getJSONArray("stops").getJSONObject(1).getJSONArray("nextStopId").put("3");boolean ambiguous=false;try{NsJourney.make(branch,"123",when);}catch(Exception e){ambiguous=true;}check(ambiguous,"same-number route branch rejected instead of silently choosing a destination");
  JSONObject passing=fixture();passing.getJSONObject("payload").getJSONArray("stops").getJSONObject(0).put("status","PASSING");JSONObject skipped=NsJourney.make(passing,"123",when);check(skipped.getJSONArray("legs").getJSONObject(0).getJSONArray("intermediateStops").length()==0&&skipped.getJSONArray("_stationCodes").length()==3,"passing stations supply geometry but are not boarding stops");
  JSONObject emptyPassing=fixture();JSONObject pass=emptyPassing.getJSONObject("payload").getJSONArray("stops").getJSONObject(0);pass.put("status","PASSING").put("arrivals",new JSONArray()).put("departures",new JSONArray());check(NsJourney.make(emptyPassing,"123",when).getJSONArray("_stationCodes").length()==3,"untimed passing node does not break a connected route");
  JSONObject offset=fixture();offset.getJSONObject("payload").getJSONArray("stops").getJSONObject(1).getJSONArray("departures").getJSONObject(0).put("plannedTime","2026-11-13T11:00:00+0100").put("actualTime","2026-11-13T11:00:00+0100");check(NsJourney.make(offset,"123",when).getJSONArray("legs").getJSONObject(0).getString("startTime").endsWith("+01:00"),"compact NS timezone offsets are normalized");
  boolean wrongDay=false;try{NsJourney.make(fixture(),"123","2026-11-16T10:05:00Z");}catch(Exception e){wrongDay=true;}check(wrongDay,"answer outside requested day rejected");System.out.println("TOTAL "+count+" checks");
 }
}
